  ('augsoffn-wiara-pfead', 'augsoffn wiara Pfead', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'angesoffen wie ein Pferd', '[{"kategorie": "wörtlich", "text": "\"besoffen wie ein Pferd\" (Pferde saufen große Mengen Wasser, also wird „saufen wie ein Pferd“ als Bild für \"viel trinken\" verwendet)"}, {"kategorie": "", "text": "[[angesoffen wie ein Indianer]]"}, {"kategorie": "", "text": "[[angesoffen]] wie ein Radi"}, {"kategorie": "", "text": "[[angesoffen]] wie ein Häusltschick"}]'::jsonb, ''),
  ('da-heisl-louis-hod-drei-pfeadaln-aum-schdrich-renna', 'Da Heisl-Louis hod drei Pfeadaln aum Schdrich renna!', '', '', '', 'Wiener Gaunersprache', 'Der Häusl-Louis hat drei Pferdchen am Strich', '[{"kategorie": "wörtlich, Gaunersprache", "text": "\"Der Häusl-Louis [Zuhälter] lässt drei Mädchen für ihn anschaffen gehen\""}, {"kategorie": "", "text": "Der Häusl-Louis [Zuhälter] hat drei [[Rösser]] rennen!  3. Der Häusl-Louis hat drei Rösser im Stall, die für ihn anschaffen gehen!"}]'::jsonb, ''),
