  ('in-deifae-sei-easchda-haaza-wean', 'in Deifä sei easchda Haaza wean', '', '', '', '', 'des Teufels erster Heizer werden', '[{"kategorie": "wörtlich", "text": "\"zum ersten Heizer des Teufels werden\""}, {"kategorie": "scherzhaft für", "text": "\"ins Fegefeuer wandern\", sterben, das Zeitliche segnen, [[ein]] Bankerl reißen, [[die]] Hammerln aufstellen, [[ins]] Gras beißen, [[die]] Erdäpfel von unten ansehen, [[den]] Löffel abgeben"}]'::jsonb, ''),
  ('im-pfusch-hackln', 'im Pfusch hackln', '', '', '', '', 'im Pfusch hackeln', '[{"kategorie": "", "text": "schwarz arbeiten"}, {"kategorie": "", "text": "illegale Arbeit verrichten"}, {"kategorie": "", "text": "unter der Hand arbeiten"}, {"kategorie": "", "text": "mit Schwarzarbeit Geld verdienen"}]'::jsonb, ''),
  ('aum-pfusch-gee', 'aum Pfusch gee', '', '', '', '', 'auf den Pfusch gehen', '[{"kategorie": "", "text": "schwarz arbeiten"}, {"kategorie": "", "text": "illegale Arbeit verrichten"}, {"kategorie": "", "text": "unter der Hand arbeiten"}, {"kategorie": "", "text": "mit Schwarzarbeit Geld verdienen"}]'::jsonb, ''),
  ('pfuschn-gee', 'pfuschn gee', '', '', '', '', 'pfuschen gehen', '[{"kategorie": "wörtlich", "text": "[[auf den Pfusch gehen]]"}, {"kategorie": "", "text": "schwarz arbeiten, illegale Arbeit verrichten, unter der Hand arbeiten, mit Schwarzarbeit Geld verdienen"}]'::jsonb, ''),
  ('schwoaz-hackln', 'schwoaz hackln', '', '', '', '', 'schwarz hackeln', '[{"kategorie": "wörtlich", "text": "\"schwarz [unangemeldet] arbeiten\""}, {"kategorie": "", "text": "illegale Arbeit verrichten, unter der Hand arbeiten"}, {"kategorie": "", "text": "mit Schwarzarbeit Geld verdienen, [[pfuschen]]"}]'::jsonb, ''),
  ('si-schleppds-waeschbinkl-ausse-in-hof-zum-trocknan', 'Si schleppds Wäschbinkl ausse in Hof zum Trocknan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie schleppt das Wäschebinkel hinaus in den Hof zum Trocknen!', '[{"kategorie": "wörtlich", "text": "\"Sie schleppt das Wäschebündel hinaus in den Hof zum Trocknen!\"  2. Sie trägt das Wäschebündel in den Hof, um es zum Trocknen aufzuhängen!  3. Sie bringt das Wäschebündel nach draußen, damit die es an der Luft trocknet!"}]'::jsonb, ''),
  ('bitschibatschi-mit-wem-sei', 'bitschibatschi mit wem sei', '', '', '', '', 'pitschi-patschi mit jemandem sein', '[{"kategorie": "wörtlich", "text": "\"auf pitschi-patschi [\"Tatschnähe\"] mit jemandem sein\" (von [[pitschen]] bzw. [[patschen]] = \"betatschen\" bzw. \"tätscheln\")"}, {"kategorie": "", "text": "mit jemandem eng befreundet sein, mit jemandem auf Du und Du stehen (was sich nach außen hin daran zeigt, dass man einander bei der Begrüßung stets herzlich umarmt und betatscht)"}]'::jsonb, ''),
  ('bitschibatschi-freindschofd', 'Bitschibatschi-Freindschofd', '', '', '', '', 'Pitschipatschi-Freundschaft', '[{"kategorie": "wörtlich", "text": "\"Freundschaft auf Tatschnähe\" (von [[pitschen]] bzw. [[patschen]] = \"betatschen\" bzw. \"tätscheln\")"}, {"kategorie": "", "text": "enges freundschaftliches Verhältnis (die durch Händchenhalten auch nach außen hin zur Schau gestellt wird), vertraute Verbundenheit  (was sich nach außen hin daran zeigt, dass man einander bei der Begrüßung stets herzlich umarmt und betatscht)"}]'::jsonb, ''),
  ('in-pixnduaf-is-kiatoog', 'In Pixnduaf is Kiatoog!', '', '', '', 'Wiener Kartentipplerjargon', 'In Pixendorf ist Kirtag!', '[{"kategorie": "wörtlich", "text": "\"In Piksendorf ist Kirchtag!\"  2. (Kartenspielerjargon): \"Und wieder wird Pik ausgespielt!\"  3. \"Und wieder wird die Farbe Pik aus erster Hand gespielt!\" (Nonsensspruch beim Ausspielen der Farbkarte \"Pik\" - in Anspielung auf den niederösterreichischen Ort \"Pixendorf\" [Gemeinde Michelhausen])"}]'::jsonb, ''),
  ('waunn-d-kotz-ausn-haus-is-feian-de-meis-kiatoog', 'Waunn d''Kotz ausn Haus is, feian de Meis Kiatoog!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn die Katze aus dem Haus ist, feiern die Mäuse Kirtag!', '[{"kategorie": "wörtlich", "text": "\"Wenn die Katze aus dem Haus ist, tanzen die Mäuse auf dem Tisch!\"  2. Wo keine Katze wacht, da feiern die Mäuse!  3. Ist der Chef außer Haus, lässt die Belegschaft die Puppen tanzen!"}]'::jsonb, ''),
  ('in-plan-wegschmeissn', 'in Plan wegschmeissn', '', '', '', '', 'den Plan wegschmeißen', '[{"kategorie": "wörtlich", "text": "\"den Plan über Bord werfen\""}, {"kategorie": "", "text": "sich nach Bauchgefühl orientieren"}, {"kategorie": "", "text": "sich nur noch auf seinen Bauch verlassen"}]'::jsonb, ''),
  ('mia-foeoed-da-plan', 'Mia fööd da Plan!', '', '', '', '', 'Mir fehlt der Plan!', '[{"kategorie": "wörtlich", "text": "Ich kenne mich vorne und hinten nicht aus!  2. Ich stehe auf dem Schlauch!"}]'::jsonb, ''),
  ('i-wea-des-fia-di-planian', 'I wea des fia di planian!', '', '', '', '', 'Ich werde das für dich planieren!', '[{"kategorie": "", "text": "Ich werde das für dich in Ordnung bringen!  2. Ich werde das für dich wieder ausbügeln!"}]'::jsonb, ''),
  ('si-hod-mi-plantiad-wiaran-nossn-fetzn', 'Si hod mi plantiad wiaran nossn Fetzn!', '', '', '', '', 'Sie hat mich plantiert wie einen nassen Fetzen!', '[{"kategorie": "", "text": "Sie hat mich abgewiesen wie einen nassen Fetzen!  2. Sie hat mich abblitzen lassen wie einen nassen Hund!"}]'::jsonb, ''),
  ('brav-kriagsd-a-zuckal', 'Brav, kriagsd a Zuckal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Brav, kriegst ein Zuckerl!', '[{"kategorie": "wörtlich, Mischung aus Spott, Sarkasmus und süßer Verhöhnung", "text": "\"Ganz brav – darfst dir zur Belohnung ein Gummibärli nehmen!\"  2. Brav gemacht – hol dir ein Zuckerl von der Lehrerin!  3. Jööö, brav warst! Kriegst ein Bonbon von mir!"}]'::jsonb, ''),
  ('brav-blatti', 'Brav blatti!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Brav blatti!', '[{"kategorie": "wörtlich", "text": "\"Brav platit!\" (vom tschechischen \"platit\"=\"zahlen\")"}, {"kategorie": "scherzhaft für", "text": "\"Brav bezahlen!\"  3. \"Die Rechnung artig begleichen!\"  4. \"Die Zeche brav berappen!\""}]'::jsonb, ''),
  ('zum-schweinsbroodn-hods-knusprige-eadaepfaeplatzki-geem-aafoch-himmlisch', 'Zum Schweinsbroodn hods knusprige Eadäpfäplatzki geem - aafoch himmlisch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Zum Schweinsbraten hat es knusprige Erdäpfelplatzki gegeben - einfach himmlisch!', '[{"kategorie": "wörtlich", "text": "\"Zum Schweinsbraten hat es knusprige Kartoffelpuffer gegeben - einfach himmlisch!\"  2. Zum Schweinsbraten wurden goldbraune Erdäpfelpuffer serviert – ein wahrer Genuss!  3. Zum Bratl gab’s herrlich krosse Kartoffellaibchen – einfach köstlich!"}]'::jsonb, ''),
  ('de-vegaana-soong-gemueseplatzki-de-fleischessa-grooslaawal', 'De Vegaana soong ''Gemüseplatzki'' - de Fleischessa ''Grooslaawal''!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Veganer sagen ''Gemüseplatzki'' - die Fleischesser ''Graslaberl''!', '[{"kategorie": "wörtlich", "text": "\"Die Veganer sagen ''Gemüseplatzki'' - die Fleischesser ''Graslaibchen''!\"  2. Die Veganer sagen Gemüseplatzki – die Fleischesser nennen’s Hasenfutter im Schlafrock!  3. Veganer schwärmen von Gemüseplatzki – Fleischesser fragen sich, warum das Ding keinen Geschmack hat!"}]'::jsonb, ''),
  ('amoi-mit-da-plaudamiarl-im-lift-schdecknbleibm-und-du-kennsd-ia-gaunzes-leebm', 'Amoi mit da Plaudamiarl im Lift schdecknbleibm - und du kennsd ia gaunzes Leebm!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Einmal mit der Plaudermarie im Lift steckenbleiben – und du kennst ihr ganzes Leben!', '[{"kategorie": "wörtlich", "text": "\"Einmal mit der Quasselstrippe im Lift steckenbleiben – und du kennst ihr ganzes Leben!\"  2. Eine Liftfahrt mit der Plaudertasche reicht – und du kennst ihre Jugend, ihre Ex-Männer und den Namen vom Friseur!  3. Einmal gefangen im Lift mit der Tratschtante – und du kennst nicht nur ihr Leben, sondern auch ihre Meinung zu deinem!"}]'::jsonb, ''),
  ('de-plauschmiarl-hod-wiida-ollas-ausplaudad-do-brauchsd-ka-radio-mea', 'De Plauschmiarl hod wiida ollas ausplaudad - do brauchsd ka Radio mea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Plauschmirl hat wieder alles ausgeplaudert - da brauchst du kein Radio mehr!', '[{"kategorie": "wörtlich", "text": "\"Die Plauschmarie hat wieder alles ausgeplaudert - da brauchst du kein Radio mehr!\"  2. Die Quasseltante hat wieder alles ausgeplaudert - gratis und ungefragt!  3. Die Plaudertasche war wieder in Hochform – von der kriegst du Nachrichten, Wetter und Nachbarschaftsklatsch in einem Aufwasch!"}]'::jsonb, ''),
  ('waunn-dea-soogd-ea-kummd-auf-an-kuazn-plausch-vuabei-iwanochda-a-jeeds-moi-bei-mia', 'Waunn dea soogd, ea kummd auf an kuazn Plausch vuabei, iwanochda a jeeds Moi bei mia!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der sagt, er kommt auf einen kurzen Plausch vorbei, übernachtet er jedes Mal bei mir!', '[{"kategorie": "wörtlich", "text": "\"Wenn er sagt, er schaut nur kurz zum Plaudern vorbei, bleibt er jedes Mal über Nacht!\"  2. Der kommt immer nur auf einen kurzen Plausch – bleibt dann aber jedes Mal bis zum nächsten Tag!  3. Nur kurz quatschen? Bei ihm heißt das: Zahnbürste auspacken und ab auf die Couch!"}]'::jsonb, ''),
  ('a-plauschal-in-eean-kaunn-kaana-vaweean', 'A Plauschal in Eean kaunn kaana vaweean!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein Plauscherl in Ehren kann keiner verwehren!', '[{"kategorie": "wörtlich", "text": "\"Ein Pläuschchen in Ehren kann keiner verwehren!\"  2. Ein nettes Gespräch zur rechten Zeit ist immer willkommen!  3. Ein bisschen quatschen geht immer!"}]'::jsonb, ''),
  ('i-mogs-ned-waunnd-leit-hinta-mein-ruckn-iwa-mi-plauschn', 'I mogs ned, waunnd Leit hinta mein Ruckn iwa mi plauschn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich mag''s nicht, wenn die Leute hinter meinem Rücken über mich plauschen!', '[{"kategorie": "wörtlich", "text": "\"Ich mag es nicht, wenn die Leute hinter meinem Rücken über mich lästern!\"  2. Ich kann es nicht leiden, wenn andere hinter meinem Rücken schlecht über mich reden!  3. Ich steh nicht drauf, wenn hinter meinem Rücken über mich getratscht wird!"}]'::jsonb, ''),
  ('treff-ma-uns-auf-an-schbritza-und-tua-ma-a-bissl-plauschn', 'Treff ma uns auf an Schbritza und tua ma a bissl plauschn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Treffen wir uns auf einen Spritzer und tun wir ein bisschen plauschen!', '[{"kategorie": "wörtlich", "text": "\"Lass uns was trinken gehen und gemütlich miteinander plaudern!\"  2. Setzen wir uns auf einen Spritzer zusammen und [[gatschen]] wir ein wenig!  3. Komm, wir kippen uns einen Spritzwein rein und unterhalten uns ganz zwanglos miteinander!"}]'::jsonb, ''),
  ('plauschds-ned', 'Plauschds ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Plauscht nicht!', '[{"kategorie": "wörtlich", "text": "\"Nun übertreibt mal nicht!\"  2. \"Jetzt mal halblang!\"  3. \"Erzählt keine Märchen!\"  4. \"Reeds kan [[Schaas]]!"}]'::jsonb, ''),
  ('dea-is-a-soiche-plauschn-dass-da-allaa-vom-zuahean-de-uawaschln-bluadn', 'Dea is a soiche Plauschn, dass da allaa vom Zuahean de Uawaschln bluadn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der ist eine solche Plauschen, dass dir allein vom Zuhören die Ohren bluten!', '[{"kategorie": "wörtlich", "text": "\"Der ist eine solche Quasselstrippe, dass dir allein vom Zuhören die Ohren bluten!\"  2. Diese Plaudertasche sabbelt dir die Ohren ab - zuerst das eine, dann das andere!  3. Bei dem Dauerquatscher denkst du irgendwann: Bitte, lieber Gott, nimm mir das Gehör!"}]'::jsonb, ''),
  ('de-plauscharei-bei-kuchn-und-kaffee-hod-uns-guad-tau-jetzd-hauma-uns-olle-wiida-liib', 'De Plauscharei bei Kuchn und Kaffee hod uns guad tau - jetzd hauma uns olle wiida liib!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Plauscherei bei Kuchen und Kaffee hat uns gut getan - jetzt haben wir uns alle wieder lieb!', '[{"kategorie": "wörtlich", "text": "\"Die zwanglose Plauderei bei Kuchen und Kaffee hat uns gut getan - jetzt haben wir uns alle wieder lieb!\"  2. Die entspannte Unterhaltung bei Kaffee und Kuchen hat Wunder gewirkt – jetzt sind wir alle wieder versöhnt!  3. Die gemütliche Tratscherei bei Kuchen und Kaffee hat die Stimmung deutlich aufgehellt - jetzt ist alles wieder im Lot!"}]'::jsonb, ''),
  ('heads-auf-mit-da-plauscharei-i-bin-jo-ned-auf-da-nuudlsuppn-daheagschwumman', 'Heads auf mit da Plauscharei - I bin jo ned auf da Nuudlsuppn daheagschwumman!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hört auf mit der Plauscherei - ich bin ja nicht auf der Nudelsuppe dahergeschwommen!', '[{"kategorie": "wörtlich", "text": "\"Jetzt übertreibt mal nicht - ich bin ja nicht von gestern!\"  2. Hört auf mit euren Schwindeleien, ihr Märchenerzähler!  3. Jetzt haltet den Ball mal flach - ich bin nicht blöd, nur nett erzogen!"}]'::jsonb, ''),
  ('a-plauscharei-hinta-mein-buugl-vatroog-i-goa-ned', 'A Plauscharei hinta mein Buugl vatroog I goa ned!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Eine Plauscherei hinter meinem Buckel vertrag ich gar nicht!', '[{"kategorie": "wörtlich", "text": "\"Heimliches Getuschel hinter meinem Rücken vertrag ich gar nicht!\"  2. Hinterfotziges Gelaber kann ich überhaupt nicht ausstehen!  3. Wenn hinter meinem Rücken gelästert wird, hört sich der Spaß für mich auf!"}]'::jsonb, ''),
  ('des-ausroin-vom-taag-woara-aanzige-gadscharei-de-hoibe-kuchl-pickd', 'Des Ausroin vom Taag woara aanzige Gadscharei - de hoibe Kuchl pickd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Das Ausrollen des Teigs war eine einzige Gatscherei - die halbe Küche pickt!', '[{"kategorie": "wörtlich", "text": "\"Beim Ausrollen ist der halbe Teig picken geblieben – eine einzige Batzerei!\"  2. Das war eine einzige Schmiererei - alles voller Teig, alles pappig!  3. Das Ausrollen des Teigs ist zu einer einzigen Gatschpartie geworden - überall in der Küche klebt''s jetzt!"}]'::jsonb, ''),
  ('gatscharei-aum-heisl-gatscharei-aum-gaung-gatscharei-im-buero-de-fiama-is-a-aanziga-trotschvarein', 'Gatscharei aum Heisl, Gatscharei aum Gaung, Gatscharei im Büro - de Fiama is a aanziga Trotschvarein!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Gatscherei auf’m Häusl, Gatscherei am Gang, Gatscherei im Büro – die Firma ist ein einziger Tratschverein!', '[{"kategorie": "wörtlich", "text": "\"Getuschel auf dem Klo, Geplapper auf dem Flur, Plauscherei im Büro – die Firma ist ein einziger Quasselclub!\"  2. Hier wird mehr gequatscht als gearbeitet – die Firma ist ein einziger Tratschverein!  3. Überall wird gequatscht, getratscht und gemunkelt – die Firma ist mehr Plauschverein als Arbeitsplatz!"}]'::jsonb, ''),
  ('a-jeeda-gatschn-ghead-a-watschn', 'A jeeda Gatschn ghead a Watschn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Jeder Gatschen g''hört ''ne Watschen!', '[{"kategorie": "wörtlich", "text": "\"Jede Tratschen kriegt ''ne Klatschen!\"  2. Jedem Lästermaul gehört eins auf die Fresse!  3. Jedem Klatschmaul gebührt eins auf die Goschen!"}]'::jsonb, ''),
  ('gatschd-wiad-imma-iwa-dee-dee-ned-do-san', 'Gatschd wiad imma iwa dee, dee ned do san!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Gegatscht wird immer über die, die nicht da sind!', '[{"kategorie": "wörtlich", "text": "\"Getratscht wird immer über die, die gerade nicht da sind!\"  2. Wer nicht anwesend ist, wird zwangsläufig Gesprächsthema Nummer eins!  3. Gemauschelt wird stets über alle Nichtanwesenden, die sich nicht wehren können!"}]'::jsonb, ''),
  ('im-gaunz-haus-gatschns-scho-iwa-di', 'Im gaunz Haus gatschns scho iwa di!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im ganzen Haus gatschen sie schon über dich!', '[{"kategorie": "wörtlich", "text": "\"Im ganzen Haus gatschen sie schon über dich!\"  2. Im ganzen Haus zerreißen sie sich schon das Maul über dich!  3. Im ganzen Haus lästern sie schon über dich!"}]'::jsonb, ''),
  ('a-gatschal-mit-haendy-is-wiara-megafon-auf-raadln', 'A Gatschal mit Händy is wiara Megafon auf Raadln!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Gatscherl mit Handy ist wie ein Megafon auf Rädern!', '[{"kategorie": "wörtlich", "text": "\"Ein Schnatterentlein mit Handy ist wie ein Megafon auf Rädern!\"  2. Eine [[Tratschen]] mit Smartphone ist wie eine Lokalzeitung mit Push-Nachrichten!  3. Eine Plaudertasche mit Smartphone ist wie ein rollender Rundfunksender!"}]'::jsonb, ''),
  ('des-maadl-woa-schoo-ois-kind-a-klaans-tratschal-owa-jetzt-is-a-muadstrumm-trotschkanoon', 'Des Maadl woa schoo ois Kind a klaans Tratschal - owa jetzt is a muadstrumm Trotschkanoon!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Mädel war schon als Kind ein kleines Tratscherl - aber jetzt ist sie eine mordstrumm Tratschkanone!', '[{"kategorie": "wörtlich", "text": "\"Das Mädel war schon als Kind eine kleine Plaudertasche – aber jetzt ist sie eine mordstrumm Tratschkanone!\"  2. Sie war schon im Kindergarten ein kleines Plappermäulchen – aber heute ist sie ein wandelndes Gerüchteportal!  3. Ich kenn sie noch als Schnatterentlein von der Sandkiste - aber jetzt ist sie eine ausgewachsene Lästermaschine!"}]'::jsonb, ''),
  ('auf-a-gatschal-vuabeikumma', 'auf a Gatschal vuabeikumma', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf ein Gatscherl vorbeikommen', '[{"kategorie": "wörtlich", "text": "\"auf ein kleines Schwätzchen vorbeikommen\""}, {"kategorie": "", "text": "\"auf einen kurzen Plausch vorbeischauen\""}, {"kategorie": "", "text": "\"auf ein [[Tratscherl]] vorbeikommen\""}, {"kategorie": "", "text": "\"auf ein kleines [[Plauscherl]] vorbeischauen\""}]'::jsonb, ''),
  ('imma-waunna-soogd-i-soi-auf-a-klaans-gatschal-vuabeikumman-laund-i-bei-eam-im-bett', 'Imma waunna soogd, I soi auf a klaans Gatschal vuabeikumman, laund I bei eam im Bett!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Immer wenn er sagt, ich soll auf ein kleines Gatscherl vorbeikommen, lande ich bei ihm im Bett!', '[{"kategorie": "wörtlich", "text": "\"Immer wenn er sagt, ich soll auf ein kleines Schwätzchen vorbeikommen, endet’s bei ihm unter der Bettdecke!\"  2. Wenn er ‚nur kurz quatschen‘ will, kann ich gleich die Unterwäsche zu Hause lassen!  3. Seine Einladung zu einem kurzen Plausch, endet regelmäßig horizontal auf der Matratze!"}]'::jsonb, 'auf a Gatschal vuabeikumma'),
  ('auf-a-tratschal-vuabeikumma', 'auf a Tratschal vuabeikumma', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf ein Tratscherl vorbeikommen', '[{"kategorie": "wörtlich", "text": "\"auf ein kleines Schwätzchen vorbeikommen\""}, {"kategorie": "", "text": "\"auf einen kurzen Plausch vorbeischauen\""}, {"kategorie": "", "text": "\"auf ein [[Gatscherl]] vorbeikommen\""}, {"kategorie": "", "text": "\"auf ein kleines [[Plauscherl]] vorbeischauen\""}]'::jsonb, ''),
