  ('do-heascht-de-laeaemung', 'Do heascht de Läämung!', '', '', '', '', 'Da herrscht die Lähmung!', '[{"kategorie": "", "text": "Da ist die Stimmung auf null!  2. Da herrscht tote Hose!  3. Da herrscht totale Stimmungsflaute!"}]'::jsonb, ''),
