  ('si-zuwelaanan', 'si zuwelaanan', '', '', '', 'Grundwortschatz Wienerisch', 'sich hinzulehnen', '[{"kategorie": "wörtlich", "text": "\"sich heranlehnen\" (vom mittelhochdeutschen \"lënen\"=\"anlehnen\")"}, {"kategorie": "allg.", "text": "sich ein Stück näher an jemandem heransetzen, heranlehnen. herandrücken, heranschmiegen"}]'::jsonb, 'Laan di zuwe!'),
