  ('leibschissl-auf-raaln', 'Leibschissl auf Raaln', '', '', '', '', 'Leibschüssel auf Rädern', '[{"kategorie": "wörtlich", "text": "\"Bettschüssel auf Rädern\""}, {"kategorie": "scherzhaft für", "text": "kleines Auto, [[Spuckerl]], [[Schnellsieder]], [[Gogomobil]], [[Scheißerl]], [[Speibdriachal]]"}]'::jsonb, ''),
  ('a-scheene-leich', 'a scheene Leich', '', '', '', '', 'eine schöne Leich', '[{"kategorie": "wörtlich", "text": "\"eine schöne Leichenfeier\" (die \"schöne Leich\" war in Wien schon immer wichtig, da sie Ausdruck des gesellschaftlichen Status war, weshalb in der Folge aus den[[Pompfüneberern]] gegen Aufpreis bezahlte Trauergäste wurden. Ohne trauernde Hinterbliebene beerdigt zu werden, galt in Wien lange Zeit als Schande)"}, {"kategorie": "allg.", "text": "\"ehrenvoller Abgang\", prunkvolle Bestattung, Beisetzung, Trauerfeier, ehrenvolles Leichenbegängnis"}]'::jsonb, ''),
  ('a-gschminkte-leich', 'a gschminkte Leich', '', '', '', '', 'eine geschminkte Leiche', '[{"kategorie": "wörtlich", "text": "\"ein geschminkter Leichnam\" (vom mittelhochdeutschen \"līch\"=\"Leiche\")"}, {"kategorie": "Mechanikerjargon, scherzhaft für", "text": "\"aufgebrezelter Schrotthaufen\", \"Mogelpackung auf Rädern\" (nach außen hin schön hergerichteter, in Wirklichkeit aber nur notdürftig reparierter Gebrauchtwagen, der zu einem weit überhöhten Preis angeboten wird)"}]'::jsonb, ''),
