  ('a-leichte', 'a Leichte', '', '', '', 'Wiener Gaunersprache', 'eine Leichte', '[{"kategorie": "wörtlich, Kurzform für", "text": "(a) \"eine leichte Ohrfeige\", (b) \"ein leichter Hieb\";  (c) \"eine leichte Watschen\""}, {"kategorie": "fig.", "text": "leichter Rückschlag, kleiner Dämpfer, \"kurzer Durchhänger\""}]'::jsonb, ''),
  ('wem-a-leichte-mitgeem', 'wem a Leichte mitgeem', '', '', '', 'Wiener Gaunersprache', 'jemandem eine Leichte mitgeben', '[{"kategorie": "wörtlich", "text": "\"jemandem eine leichte Ohrfeige mit auf den Weg geben\""}, {"kategorie": "", "text": "jemandem vor dessen Abgang noch einen leichten Hieb versetzen"}, {"kategorie": "", "text": "jemandem noch einen leichten Schlag mit auf den Weg geben"}, {"kategorie": "fig.", "text": "jemandem einen leichten Dämpfer verpassen, jemanden leicht zurückwerfen, jemanden leicht ausbremsen, jemandem vorübergehend den Wind aus den Segeln nehmen"}]'::jsonb, 'De Zeit im Hääfn hod ma a Leichte mitgeem, owa jetzt bin I wiida voi do!'),
  ('de-zeit-im-haeaefn-hod-ma-a-leichte-mitgeem-owa-jetzt-bin-i-wiida-voi-do', 'De Zeit im Hääfn hod ma a Leichte mitgeem, owa jetzt bin I wiida voi do!', '', '', '', 'Wiener Gaunersprache', 'Die Zeit im Häfen hat mir eine Leichte mitgegeben, aber jetzt bin ich wieder voll da!', '[{"kategorie": "wörtlich", "text": "\"Die Zeit im Gefängnis hat mich ein wenig zurückgeworfen, aber jetzt bin ich wieder voll da!\"  2. Die Haftzeit hat mich ein wenig ausgebremst, aber jetzt bin ich wieder voll im Leben!  3. Die Zeit hinter Gittern hat mich ein Stück weit zurückgeworfen – doch jetzt hab ich wieder Boden unter den Füßen!"}]'::jsonb, ''),
  ('dahaam-leids-mi-nimma', 'Dahaam leids mi nimma!', '', '', '', '', 'Daheim leidet es mich nimmer!', '[{"kategorie": "", "text": "Ich bin es leid, zu Hause zu bleiben!  2. Daheim halte ich es nicht mehr aus!"}]'::jsonb, ''),
