  ('des-is-leo', 'Des is Leo!', '', '', '', '', 'Das ist Leo!', '[{"kategorie": "wörtlich", "text": "\"Das ist im geschützten Bereich!\"  2. (fig.) Das ist tabu!  3. Das ist unangreifbar!"}]'::jsonb, ''),
  ('si-ins-leo-schbueuen', 'si ins Leo schbüün', '', '', '', '', 'sich ins Leo spielen', '[{"kategorie": "wörtlich", "text": "\"sich heimlich in den geschützten Bereich verdrücken\""}, {"kategorie": "", "text": "sich unangreifbar machen"}, {"kategorie": "", "text": "sich jeder Verantwortung entziehen"}]'::jsonb, ''),
  ('si-leopoidn', 'si leopoidn', '', '', '', '', 'sich leopolden', '[{"kategorie": "wörtlich", "text": "\"sich aus einem Geschehen heraushalten\" (verballhornt vom mittelhochdeutschen \"polten\"=\"sich ausnehmen\")"}, {"kategorie": "", "text": "sich enthalten, sich nicht beteiligen, \"passen\" (beim Kartenspiel, bei einem Geschäft, etc.)"}]'::jsonb, ''),
  ('si-hod-a-schdimm-wiara-leachal', 'Si hod a Schdimm wiara Leachal!', '', '', '', '', 'Sie hat eine Stimme wie ein Lercherl!', '[{"kategorie": "wörtlich", "text": "\"Ihre Stimme klingt so schön wie die einer kleinen Lerche\""}, {"kategorie": "fig.", "text": "Sie singt so schön wie eine Nachtigall!  3. Sie hat eine himmlische Stimme!"}]'::jsonb, ''),
  ('s-leachal-von-heanois', 's''Leachal von Heanois', '', '', '', '', 'das Lercherl von Hernals', '[{"kategorie": "wörtlich", "text": "\"die kleine Lerche von Hernals\" (Spitzname von Barbara \"Betty\" Fischer, Wiener Operettensängerin und Sopranistin [1887-1969], die ob ihres \"himmlischen Gesangs\" große Berühmtheit erlangte)"}, {"kategorie": "", "text": "Titel des berühmten Liedes aus der Operette \"Hoheit tanzt Walzer\" von Leo Ascher (1880-1942)"}, {"kategorie": "", "text": "Gasthaus mit traditioneller Wirtshauskost im 17. Wiener Gemeindebezirk ([[Hernals]])"}]'::jsonb, ''),
  ('neem-dera-wiad-jeds-luada-zum-leachal', 'Neem dera wiad jeds Luada zum Leachal!', '', '', '', '', 'Neben der da wird jedes Luder zum Lercherl!', '[{"kategorie": "fig.", "text": "\"Neben ihr wird jede Wildkatze zahm!\"  2. Neben ihr wird selbst der ärgste Rüpel zum Schmusetier!"}]'::jsonb, ''),
  ('brunzn-wiara-leitabaea', 'brunzn wiara Leitabäa', '', '', '', '', 'brunzen wie ein Leithabär', '[{"kategorie": "wörtlich", "text": "\"pinkeln wie ein Bär aus dem Leithagebirge\" (5-7km breiter Höhenrücken an der Grenze von Niederösterreich und Burgenland, wobei \"Leithabär\" die Verballhornung von \"Läuterbua\"=\"Ministrant\" ist)"}, {"kategorie": "scherzhaft für", "text": "mit starkem Strahl Wasser lassen, mächtig stark urinieren, [[schiffen]], [[seichen]], [[den]] Familienstrumpf auswinden"}]'::jsonb, ''),
  ('auf-da-leitung-schdee', 'auf da Leitung schdee', '', '', '', '', 'auf der Leitung stehen', '[{"kategorie": "wörtlich", "text": "\"auf der Telefonleitung stehen und deshalb nichts verstehen\" (Redewendung stammt aus einer Zeit, als die Telefontechnik noch in den Kinderschuhen steckte)"}, {"kategorie": "scherzhaft für", "text": "begriffsstutzig sein, ein Brett vor dem Kopf haben, auf dem [[Schlauch]] stehen"}]'::jsonb, ''),
  ('aufn-schlauch-schdee', 'aufn Schlauch schdee', '', '', '', '', 'auf dem Schlauch stehen', '[{"kategorie": "wörtlich", "text": "\"auf dem Gartenschlauch stehen und sich wundern, dass vorne kein Wasser rauskommt\""}, {"kategorie": "scherzhaft für", "text": "begriffsstutzig sein, ein Brett vor dem Kopf haben, auf der [[Leitung]] stehen"}]'::jsonb, ''),
  ('a-launge-leitung-haum', 'a launge Leitung haum', '', '', '', '', 'eine lange Leitung haben', '[{"kategorie": "wörtlich", "text": "\"eine lange Stromleitung haben, sodass es lange dauert, bis der Strom sein Ziel erreicht\""}, {"kategorie": "fig.", "text": "Dinge nur sehr langsam oder schwer verstehen, begriffsstutzig sein, eine langsame Auffassungsgabe haben"}]'::jsonb, '')
